<script setup lang="ts">
defineProps<{report:any}>()
function exportReport(r:any){
 const text=`# 学习报告 · ${r.scene_title}\n\n会话：${r.session_id}\n\n目标：${r.goal}\n\n语言目标：${r.language_goals}\n\n- 我的发言：${r.user_messages} 条\n- 角色回复：${r.ai_messages} 条\n- 英文词数：${r.english_words}\n- 不重复英文词：${r.unique_english_words}\n\n## 最近表达\n${r.expressions.map((e:any)=>'- '+e.content).join('\n')}\n\n## 对话中的提示\n${r.hints.length?r.hints.map((h:any)=>'- '+h.content).join('\n'):'暂无 Hint 提示。'}\n\n## 下一步\n${r.next_step}\n\n${r.note}\n`
 const url=URL.createObjectURL(new Blob([text],{type:'text/markdown;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`学习报告-${r.session_id}.md`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)
}
</script>
<template><section v-if="report" class="learning-report"><div class="eyebrow">LEARNING REVIEW</div><h2>{{report.scene_title}}</h2><p>{{report.goal}}</p><div class="report-stats"><div v-for="stat in [['我的发言',report.user_messages],['角色回复',report.ai_messages],['英文词数',report.english_words],['不重复词',report.unique_english_words]]" :key="stat[0]"><strong>{{stat[1]}}</strong><span>{{stat[0]}}</span></div></div><h3>语言目标</h3><p>{{report.language_goals}}</p><h3>最近的表达</h3><p v-if="!report.expressions.length">还没有发言，完成一轮对话后再来查看。</p><blockquote v-for="e in report.expressions" :key="e.message_id">{{e.content}}</blockquote><h3>对话中的提示</h3><p v-if="!report.hints.length">当前记录没有 Hint 提示；这不代表没有语法错误。</p><p v-for="h in report.hints" :key="h.message_id">{{h.content}}</p><h3>下一步练习</h3><p>{{report.next_step}}</p><p class="muted">{{report.note}}</p><el-button type="primary" @click="exportReport(report)">导出学习报告 Markdown</el-button></section></template>
<style scoped>.report-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:24px 0}.report-stats>div{padding:18px;background:#eef4ea;border-radius:10px;text-align:center}.report-stats strong{display:block;font-size:26px}.report-stats span{display:block;font-size:12px;margin-top:8px}blockquote{border-left:3px solid #90af98;padding:12px;background:#f7f9f5;white-space:pre-wrap}h3{font-size:17px;margin-top:24px}@media(max-width:600px){.report-stats{grid-template-columns:1fr 1fr}}</style>
